"Bir maddeye tıklayınca harita o güne gider, değişen yeri gösterir ve ayrıntı penceresi açılır (açıklama, görsel, kaynak). Böylece kronoloji ile harita birbirini doğrular.":["Όταν κάνετε κλικ σε ένα στοιχείο, ο χάρτης πηγαίνει σε εκείνη την ημέρα, δείχνει το σημείο που άλλαξε και ανοίγει το παράθυρο λεπτομερειών (περιγραφή, εικόνα, πηγή). Έτσι η χρονολογία και ο χάρτης επιβεβαιώνουν ο ένας τον άλλον.", "0c30189d"],
"Bir tarih yazın.":["Γράψτε μια ημερομηνία.", "d118a98f"],
"Bir şehrin bir belgede ilk kez anıldığını anlatan maddeler (etiket: sehir-kronolojisi). Kronoloji sütunundaki süzgeçle ortak ayar.":["Στοιχεία που αφηγούνται την πρώτη αναφορά μιας πόλης σε ένα έγγραφο (ετικέτα: sehir-kronolojisi). Κοινή ρύθμιση με το φίλτρο της στήλης χρονολογίας.", "82fbb7a3"],
