"Bu atlas, zaman ilerledikçe devlet sınırlarının nasıl değiştiğini gösterir. Haritanın yanında o günün kronolojisi ve hükümdarı akar: bir madde okuduğunuzda haritada tam o değişimi görürsünüz.":["Αυτός ο άτλαντας δείχνει πώς αλλάζουν τα σύνορα των κρατών καθώς περνά ο χρόνος. Δίπλα στον χάρτη ρέει η χρονολογία εκείνης της ημέρας και ο ηγεμόνας: όταν διαβάζετε ένα στοιχείο, βλέπετε στον χάρτη ακριβώς εκείνη την αλλαγή.", "f078a759"],
