"Bu durak SEÇİLMİŞTİR, kaynaktan alınmamıştır.":["Αυτή η στάση είναι ΕΠΙΛΕΓΜΕΝΗ, δεν προέρχεται από πηγή.", "39539df8"],
"Bu günde":["Αυτή την ημέρα", "90a91bd7"],
"Bu günde haritada bu adda yer yok":["Αυτή την ημέρα δεν υπάρχει στον χάρτη μέρος με αυτό το όνομα", "26396a23"],
"Bu günde haritada olan bir yerin adını yazın: şehir · kale · liman · bölge · ülke. Listeden tıklayın ya da ↑/↓ + Enter ile seçin (Esc kapatır). Henüz haritada olmayan yer listede çıkmaz.":["Γράψτε το όνομα ενός μέρους που υπάρχει στον χάρτη αυτή την ημέρα: πόλη · φρούριο · λιμάνι · περιοχή · χώρα. Κάντε κλικ στη λίστα ή επιλέξτε με ↑/↓ + Enter (το Esc κλείνει). Μέρη που δεν υπάρχουν ακόμη στον χάρτη δεν εμφανίζονται στη λίστα.", "c705d7a5"],
"Bu günde haritada olan yeri ara":["Αναζήτηση μέρους που υπάρχει στον χάρτη αυτή την ημέρα", "1b680f02"],
