"Bu kutuya bir tarih yazıp Enter tuşuna basın; harita ve kronoloji o güne atlar.":["Γράψτε μια ημερομηνία σε αυτό το πεδίο και πατήστε Enter· ο χάρτης και η χρονολογία πηγαίνουν σε εκείνη την ημέρα.", "5f74d521"],
"Bu kutuya bir yer adı yazın: şehir, kale, liman, bölge ya da ülke.":["Γράψτε ένα όνομα μέρους σε αυτό το πεδίο: πόλη, φρούριο, λιμάνι, περιοχή ή χώρα.", "0fb6f40c"],
