"Bu maddenin dayandığı kaynakları gösterir (tıklayınca açılır).":["Δείχνει τις πηγές στις οποίες βασίζεται αυτό το στοιχείο (ανοίγει με κλικ).", "7d964465"],
"Bu maddenin kaynağı henüz yazılmadı; teyit bekliyor.":["Η πηγή αυτού του στοιχείου δεν έχει γραφτεί ακόμη· αναμένει επιβεβαίωση.", "b8384ba1"],
