"Harita o olayın gününe geçer, kronolojide madde vurgulanır. Oynatmadan, adım adım okumak için en rahat yoldur.":["Ο χάρτης πηγαίνει στην ημέρα του γεγονότος και το στοιχείο τονίζεται στη χρονολογία. Είναι ο πιο βολικός τρόπος για ανάγνωση βήμα προς βήμα, χωρίς αναπαραγωγή.", "ccb3cb08"],
