"Komşu devletlerin olayları. ⚠️ `bolge` alanı veride henüz yok — bugün `onem` vekil olarak kullanılıyor ve bu panelde BEYAN EDİLİYOR":["Γεγονότα των γειτονικών κρατών. ⚠️ Το πεδίο `bolge` δεν υπάρχει ακόμη στα δεδομένα — σήμερα χρησιμοποιείται ως υποκατάστατο το `onem` και ΔΗΛΩΝΕΤΑΙ σε αυτό το πάνελ", "32e39625"],
