"Kırpma süresi: öncesi/sonrası gösteriminin toplam süresi (milisaniye).":["Διάρκεια αναλαμπής: συνολική διάρκεια της εμφάνισης πριν/μετά (χιλιοστά του δευτερολέπτου).", "e58c5fc2"],
"Kısa bir turla ekrandaki her parçayı tanıtalım. İleri düğmesiyle (ya da sağ ok tuşuyla) ilerleyin; istediğiniz an Geç diyebilirsiniz.":["Θα σας γνωρίσουμε κάθε τμήμα της οθόνης με μια σύντομη ξενάγηση. Προχωρήστε με το κουμπί Επόμενο (ή με το δεξί βέλος)· μπορείτε να πείτε Παράλειψη όποια στιγμή θέλετε.", "c1b9a7e1"],
